<template><div class="page"><div class="page-head"><div><span>FAULT TREE ANALYSIS / SIMULATION</span><h2>仿真故障树</h2><p>故障树随当前仿真场景生成，仅保留实际触发的分支。</p></div><div class="actions"><el-select v-model="mode" style="width:180px"><el-option v-for="x in modes" :key="x" :label="x" :value="x" /></el-select><el-button type="primary" @click="run">生成故障树</el-button></div></div><el-card shadow="never"><div class="summary"><el-tag type="danger">顶事件</el-tag><b>{{ tree.root }}</b><span>场景：动力 / {{ mode }}</span></div><div class="tree"><div class="node top">{{ tree.root }}</div><div class="connector"></div><div class="gate">OR</div><div class="connector short"></div><div class="event"><div class="event-title"><span class="dot"></span>{{ tree.event }}</div><p>{{ tree.reason }}</p><el-tag type="danger" effect="plain">已触发</el-tag></div></div><el-descriptions border :column="3" class="details"><el-descriptions-item label="逻辑关系">顶事件 OR 底事件</el-descriptions-item><el-descriptions-item label="证据窗口">第 20 个采样点起</el-descriptions-item><el-descriptions-item label="分析状态"><el-tag type="success">已完成</el-tag></el-descriptions-item></el-descriptions></el-card></div></template>
<script setup>import{ref}from'vue';import{ElMessage}from'element-plus';const modes=['泄漏','泵效率下降','传感器偏置','执行器迟滞'];const mode=ref('泄漏');const maps={泄漏:['推进剂供给压力低','仿真注入：动力系统泄漏，管路压力下降'],'泵效率下降':['发动机温度升高','仿真注入：燃料泵效率衰减，温度趋势异常'],'传感器偏置':['姿态测量偏差','仿真注入：姿态传感器零点偏移'],'执行器迟滞':['控制响应迟滞','仿真注入：姿态执行器响应延迟']};const tree=ref({root:'推进系统功能异常',event:maps.泄漏[0],reason:maps.泄漏[1]});function run(){tree.value={root:'推进系统功能异常',event:maps[mode.value][0],reason:maps[mode.value][1]};ElMessage.success('故障树已按当前仿真场景更新')}</script>
<style scoped>.page{max-width:1100px}.page-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.page-head span{color:#1677ff;font-size:12px;letter-spacing:1px}.page-head h2{margin:8px 0}.page-head p{color:#718198}.actions{display:flex;gap:10px}.summary{display:flex;align-items:center;gap:12px;padding-bottom:18px;border-bottom:1px solid #edf1f5}.summary span{margin-left:auto;color:#718198;font-size:13px}.tree{text-align:center;padding:34px 10px}.node,.gate,.event{display:inline-block;border:1px solid #d9e2ee;border-radius:8px;background:#fff}.node{padding:14px 30px;border-color:#e34d59;background:#fff5f5;font-weight:600}.connector{height:26px;border-left:2px solid #e34d59;margin:auto;width:1px}.connector.short{height:18px}.gate{padding:6px 14px;border-color:#e6a23c;background:#fff8e8;font-weight:600}.event{padding:16px 24px;min-width:300px;text-align:left;border-left:4px solid #e34d59}.event-title{font-weight:600}.event p{margin:8px 0 12px;color:#718198;font-size:13px}.dot{display:inline-block;width:8px;height:8px;background:#e34d59;border-radius:50%;margin-right:8px}.details{margin-top:10px}@media(max-width:700px){.page-head{display:block}.actions{margin-top:14px;flex-wrap:wrap}.summary{flex-wrap:wrap}.summary span{width:100%;margin-left:0}}</style>
